private boolean isOffloadVariableRateSupported(@Nullable Context context) {
  if (isOffloadVariableRateSupported != null) {
    return isOffloadVariableRateSupported;
  }
  if (context != null) {
    try {
      AudioManager audioManager = (AudioManager) context.getSystemService(Context.AUDIO_SERVICE);
      if (audioManager != null) {
        String offloadVariableRateSupportedKeyValue = audioManager.getParameters(OFFLOAD_VARIABLE_RATE_SUPPORTED_KEY);
        isOffloadVariableRateSupported = offloadVariableRateSupportedKeyValue != null && offloadVariableRateSupportedKeyValue.equals(OFFLOAD_VARIABLE_RATE_SUPPORTED_KEY + "=1");
      } else {
        isOffloadVariableRateSupported = false;
      }
    } catch (NullPointerException e) {
      isOffloadVariableRateSupported = false;
    }
  } else {
    isOffloadVariableRateSupported = false;
  }
  return isOffloadVariableRateSupported;
}
